#!/bin/sh
# Path filters for CI (OpenSpec site-bundle D7). Reads changed file names on
# stdin and prints `code=true|false` and `docs=true|false` for $GITHUB_OUTPUT.
# Conservative: anything that can change the binary, the web app or the CI
# itself counts as code (skills/ is embedded in the binary, scripts/deploy*
# generate and check the deploy/ templates); docs/, the in-app help and the
# changelog count as docs. templates/ is compiled into the web app (template-library). Cases: scripts/repo-checks.test.mjs.
set -eu
files=$(cat)
# The in-app help is regenerated by every docs edit; it is docs, not code.
code_files=$(printf '%s\n' "$files" | grep -vxF 'web/src/generated/help.json' || true)
code=false
docs=false
if printf '%s\n' "$code_files" | grep -qE '^(internal/|cmd/|web/|extension/|deploy/|skills/|go\.(mod|sum)$|Dockerfile|\.dockerignore$|docker-compose\.yml$|Makefile$|\.github/|templates/|scripts/(e2e-layout|e2e-smoke|e2e-views|cli-smoke|ui-check|coolify|deploy|ci-changes|repo-checks|templates-))'; then
  code=true
fi
if printf '%s\n' "$files" | grep -qE '^(docs/|website/|web/src/generated/help\.json$|CHANGELOG\.md$|README\.md$|openspec/|scripts/(site-bundle|e2e-docs|screenshots|docs-screenshots))'; then
  docs=true
fi
echo "code=$code"
echo "docs=$docs"
